const envelope = $input || {};
const text = (value) => (typeof value === 'string' ? value.trim() : '');
const envelopeKeys = new Set(['pluginId', 'widgetId', 'product', 'resource', 'submittedBy', 'submittedAt', 'action', 'fields']);
const unknownEnvelope = Object.keys(envelope).filter((key) => !envelopeKeys.has(key));
if (unknownEnvelope.length) throw new Error('unknown_envelope_fields:' + unknownEnvelope.join(','));
const product = text(envelope.product);
const resource = text(envelope.resource);
const submittedBy = text(envelope.submittedBy);
if (!submittedBy) throw new Error('submitted_by_required');
const fields = envelope.fields && typeof envelope.fields === 'object' && !Array.isArray(envelope.fields) ? envelope.fields : null;
if (!fields) throw new Error('fields_required');
if (product !== 'sos') throw new Error('unsupported_product');
if (resource !== 'events') throw new Error('unsupported_resource');
const recordId = text(fields.event_id);
if (!/^[A-Za-z0-9_@.:+-]{1,256}$/.test(recordId)) throw new Error('record_id_invalid');
const encodedId = encodeURIComponent(recordId);
const allowed = new Set(["event_id","resolution_note"]);
const unknown = Object.keys(fields).filter((key) => !allowed.has(key));
if (unknown.length) throw new Error('unknown_fields:' + unknown.join(','));
const resolutionNote = text(fields.resolution_note);
if (resolutionNote.length > 4000) throw new Error('resolution_note_max_4000');

const audit = {
  product, resource, operation: 'emergency.close', recordId,
  pluginId: text(envelope.pluginId), widgetId: text(envelope.widgetId),
  submittedBy, submittedAt: text(envelope.submittedAt) || $now,
};

return { recordId, encodedId, resolutionNote, audit };

const response = $input || {};
const action = response.input;
const current = response.body;
if (response.statusCode !== 200 || !current || typeof current.data !== 'object' || !current.data) throw new Error('event_not_found');
if (!Number.isInteger(current.version)) throw new Error('record_version_unavailable');
const event = { ...current.data, id: String(current.data.id || current.id) };
const status = String(event.status);
if (['canceled', 'archived'].includes(status)) throw new Error('event_terminal');
if (!['monitoring', 'active', 'contained', 'resolved'].includes(status)) throw new Error('event_status_invalid');
const filter = { emergency_event_id: event.id };
return {
  event,
  version: current.version,
  action,
  queries: {
    dispatch: { where: filter, limit: 500 },
    sitrep: { where: filter, limit: 500 },
    resources: { limit: 500 },
    afterAction: { where: filter, orderBy: 'version:desc', limit: 50 },
  },
};

const response = $input || {};
const state = response.input;
if (response.statusCode !== 200 || !response.body || !Array.isArray(response.body.items)) throw new Error('query_failed_dispatch');
const rows = response.body.items.map((item) => {
  const data = item && typeof item.data === 'object' && item.data ? item.data : {};
  return { ...data, id: String(data.id || (item && item.id) || '') };
});
const total = Number(response.body.total);
if (Number.isFinite(total) && total > rows.length) throw new Error('query_truncated_dispatch');
return { ...state, dispatch: rows };

const response = $input || {};
const state = response.input;
if (response.statusCode !== 200 || !response.body || !Array.isArray(response.body.items)) throw new Error('query_failed_sitreps');
const rows = response.body.items.map((item) => {
  const data = item && typeof item.data === 'object' && item.data ? item.data : {};
  return { ...data, id: String(data.id || (item && item.id) || '') };
});
const total = Number(response.body.total);
if (Number.isFinite(total) && total > rows.length) throw new Error('query_truncated_sitreps');
return { ...state, sitreps: rows };

const response = $input || {};
const state = response.input;
if (response.statusCode !== 200 || !response.body || !Array.isArray(response.body.items)) throw new Error('query_failed_resources');
const rows = response.body.items.map((item) => {
  const data = item && typeof item.data === 'object' && item.data ? item.data : {};
  return { ...data, id: String(data.id || (item && item.id) || '') };
});
const total = Number(response.body.total);
if (Number.isFinite(total) && total > rows.length) throw new Error('query_truncated_resources');
return { ...state, resources: rows };

const response = $input || {};
const state = response.input;
if (response.statusCode !== 200 || !response.body || !Array.isArray(response.body.items)) throw new Error('query_failed_after_action_reports');
const event = state.event;
const status = String(event.status);
if (!['monitoring', 'active', 'contained', 'resolved'].includes(status)) throw new Error('event_status_invalid');
const aars = response.body.items.map((item) => {
  const data = item && typeof item.data === 'object' && item.data ? item.data : {};
  return { ...data, id: String(data.id || (item && item.id) || '') };
}).filter((aar) => String(aar.emergency_event_id ?? event.id) === String(event.id));
aars.sort((a, b) => (Number(b.version) || 0) - (Number(a.version) || 0) || String(b.id).localeCompare(String(a.id)));
const latestAaR = aars.length
  ? { id: aars[0].id, version: Number.isInteger(Number(aars[0].version)) ? Number(aars[0].version) : 1 }
  : null;
const resolutionNote = state.action.resolutionNote || (typeof event.resolution_note === 'string' ? event.resolution_note : '') || null;
const mode = status === 'resolved' ? 'idempotent' : latestAaR ? 'reuse' : 'create';
return {
  ...state,
  closedAt: $now,
  closedBy: state.action.audit.submittedBy,
  resolutionNote,
  latestAaR,
  nextVersion: latestAaR ? latestAaR.version + 1 : 1,
  mode,
};

const state = $input || {};
if (state.mode !== 'idempotent') throw new Error('unexpected_close_mode');
return {
  idempotent: true,
  operation: 'emergency.close',
  event_id: state.event.id,
  status: 'resolved',
  after_action_report_id: state.latestAaR ? state.latestAaR.id : null,
  event_version: state.version,
};

const state = $input || {};
if (state.mode !== 'reuse' || !state.latestAaR) throw new Error('unexpected_close_mode');
const aarId = String(state.latestAaR.id);
const event = state.event;
const next = {
  ...event,
  status: 'resolved',
  ended_at: state.closedAt,
  resolution_note: state.resolutionNote,
  after_action_report_id: aarId,
  resolved_by: state.closedBy,
  updated_at: state.closedAt,
};
return {
  body: { data: next, ifVersion: state.version },
  encodedId: state.action.encodedId,
  audit: { ...state.action.audit, after_action_report_id: aarId, aar_version: state.latestAaR.version },
  mode: state.mode,
};

const state = $input || {};
if (state.mode !== 'create') throw new Error('unexpected_close_mode');
const event = state.event;
const orders = state.dispatch || [];
const sitreps = state.sitreps || [];
const resources = state.resources || [];
const version = state.nextVersion;
const closedAt = state.closedAt;
const parseTime = (value) => {
  if (typeof value !== 'string' || !value.trim()) return null;
  const parsed = Date.parse(value);
  return Number.isFinite(parsed) ? parsed : null;
};
const round = (value, digits = 2) => Math.round(value * (10 ** digits)) / (10 ** digits);
const clamp = (value) => Number.isFinite(value) ? round(Math.min(100, Math.max(0, value))) : 0;
const iso = (ms) => new Date(ms).toISOString();
const severity = String(event.severity || 'medium');
const sla = { critical: 30, high: 60, medium: 120, low: 240 }[severity] || 120;
const eventStart = parseTime(event.started_at) ?? parseTime(event.created_at);
const eventEnd = parseTime(closedAt) ?? Date.now();
const timeline = [];
if (parseTime(event.created_at) !== null) timeline.push({ timestamp: iso(parseTime(event.created_at)), source: 'event', action: 'event.created', details: { event_id: event.id, title: event.title } });
if (parseTime(event.started_at) !== null) timeline.push({ timestamp: iso(parseTime(event.started_at)), source: 'event', action: 'event.started', details: { severity, event_type: event.event_type } });
let firstAssignment = null;
let completed = 0;
let canceled = 0;
const assignedResources = new Set();
for (const order of orders) {
  const created = parseTime(order.created_at);
  if (created !== null) timeline.push({ timestamp: iso(created), source: 'dispatch', action: 'dispatch.created', details: { order_id: order.id, task_title: order.task_title, priority: order.priority } });
  const assignments = Array.isArray(order.assignments) ? order.assignments : [];
  let assignedAt = null;
  for (const assignment of assignments) {
    if (!assignment || typeof assignment !== 'object') continue;
    const time = parseTime(assignment.assigned_at);
    if (time !== null) { assignedAt = time; break; }
  }
  if (assignedAt === null) assignedAt = parseTime(order.assigned_at) ?? parseTime(order.started_at);
  if (assignedAt !== null) {
    if (firstAssignment === null || assignedAt < firstAssignment) firstAssignment = assignedAt;
    timeline.push({ timestamp: iso(assignedAt), source: 'dispatch', action: 'dispatch.assigned', details: { order_id: order.id, resource_unit_id: order.assigned_resource_unit_id ?? order.assigned_user_id ?? null } });
  }
  const resourceId = order.assigned_resource_unit_id ?? order.assigned_user_id ?? null;
  if (resourceId) assignedResources.add(String(resourceId));
  const status = String(order.status ?? '');
  if (status === 'completed') {
    completed += 1;
    const completedAt = parseTime(order.completed_at) ?? parseTime(order.updated_at);
    if (completedAt !== null) timeline.push({ timestamp: iso(completedAt), source: 'dispatch', action: 'dispatch.completed', details: { order_id: order.id } });
  } else if (status === 'canceled' || status === 'rejected') {
    canceled += 1;
  }
}
let publishedSitreps = 0;
for (const sitrep of sitreps) {
  const created = parseTime(sitrep.created_at);
  if (created !== null) timeline.push({ timestamp: iso(created), source: 'sitrep', action: 'sitrep.created', details: { sitrep_id: sitrep.id, title: sitrep.title } });
  if (String(sitrep.status ?? '') === 'published') {
    publishedSitreps += 1;
    const published = parseTime(sitrep.published_at) ?? parseTime(sitrep.updated_at);
    if (published !== null) timeline.push({ timestamp: iso(published), source: 'sitrep', action: 'sitrep.published', details: { sitrep_id: sitrep.id } });
  }
}
timeline.push({ timestamp: iso(eventEnd), source: 'event', action: 'event.resolved', details: { status: 'resolved' } });
timeline.sort((a, b) => Date.parse(a.timestamp) - Date.parse(b.timestamp) || a.action.localeCompare(b.action));
const responseAt = firstAssignment ?? eventEnd;
const responded = firstAssignment !== null;
const responseMinutes = eventStart !== null && responseAt !== null ? round(Math.max(0, (responseAt - eventStart) / 60000), 1) : null;
const counted = orders.filter((order) => !['canceled', 'rejected'].includes(String(order.status ?? ''))).length;
const dispatchCompletion = counted > 0 ? round((completed / counted) * 100, 2) : 0;
const durationMs = eventStart !== null ? Math.max(0, eventEnd - eventStart) : 0;
const expectedSitreps = Math.max(1, Math.ceil(durationMs / (6 * 60 * 60 * 1000)));
const sitrepCoverage = round((Math.min(publishedSitreps, expectedSitreps) / expectedSitreps) * 100, 2);
const availableResources = resources.filter((resource) => String(resource.status ?? '') === 'available' && !assignedResources.has(String(resource.id))).length;
const denominator = availableResources + assignedResources.size;
const resourceEfficiency = denominator > 0 ? round((assignedResources.size / denominator) * 100, 2) : 0;
const speed = !responded || responseMinutes === null ? 0
  : responseMinutes <= sla ? 100
    : responseMinutes <= sla * 1.5 ? 80
      : responseMinutes <= sla * 2 ? 60
        : responseMinutes <= sla * 4 ? 40 : 20;
const overall = round(0.3 * speed + 0.3 * dispatchCompletion + 0.2 * sitrepCoverage + 0.2 * resourceEfficiency, 2);
const eventCode = String(event.event_code ?? event.id);
const aarId = ('aar-' + String(event.id) + '-v' + version).replace(/[^A-Za-z0-9_.-]/g, '-').slice(0, 180);
const summary = 'Sự kiện ' + eventCode + ' (' + String(event.title ?? '') + ') kết thúc với ' + completed + '/' + counted + ' nhiệm vụ hoàn thành. '
  + (responded ? 'Phản ứng đầu tiên sau ' + (responseMinutes ?? 0) + ' phút (SLA ' + sla + ' phút).' : 'Không ghi nhận phân công phản ứng nào.')
  + ' ' + publishedSitreps + '/' + expectedSitreps + ' SITREP đã xuất bản; ' + assignedResources.size + ' nguồn lực được điều động.';
const aar = {
  id: aarId,
  emergency_event_id: String(event.id),
  report_code: 'AAR-' + eventCode + '-v' + version,
  title: 'After-action report — ' + String(event.title ?? event.id),
  summary,
  status: 'draft',
  version,
  timeline,
  kpi: {
    response_time_minutes: responseMinutes ?? 0,
    response_sla_minutes: sla,
    response_speed_score: clamp(speed),
    dispatch_completion_rate: clamp(dispatchCompletion),
    sitrep_coverage_rate: clamp(sitrepCoverage),
    resource_efficiency_score: clamp(resourceEfficiency),
    overall_score: clamp(overall),
    dispatch_total: orders.length,
    dispatch_completed: completed,
    dispatch_canceled: canceled,
    sitrep_published: publishedSitreps,
    sitrep_expected: expectedSitreps,
    resources_assigned: assignedResources.size,
    resources_available: availableResources,
  },
  lessons_learned: [],
  recommendations: [],
  generated_by: 'sos-kpi-engine-v1',
  generated_at: closedAt,
  created_at: closedAt,
  updated_at: closedAt,
  metadata: {
    generated_by: 'sos-kpi-engine-v1',
    formula: 'overall=0.3*response+0.3*dispatch+0.2*sitrep+0.2*resource',
    event_start: eventStart === null ? null : iso(eventStart),
    event_end: iso(eventEnd),
    first_assignment_at: firstAssignment === null ? null : iso(firstAssignment),
    sla_minutes: sla,
    computed_at: closedAt,
    generated_by_user: state.closedBy,
  },
};
return { ...state, aarBody: { id: aarId, data: aar, publish: false } };

const response = $input || {};
const state = response.input;
if (response.statusCode !== 201 && response.statusCode !== 200) throw new Error('aar_create_failed');
if (!response.body || typeof response.body.id !== 'string' || !response.body.id) throw new Error('aar_response_missing_id');
const aarId = response.body.id;
const event = state.event;
const next = {
  ...event,
  status: 'resolved',
  ended_at: state.closedAt,
  resolution_note: state.resolutionNote,
  after_action_report_id: aarId,
  resolved_by: state.closedBy,
  updated_at: state.closedAt,
};
return {
  body: { data: next, ifVersion: state.version },
  encodedId: state.action.encodedId,
  audit: { ...state.action.audit, after_action_report_id: aarId, aar_version: state.nextVersion },
  mode: state.mode,
};
